<template><SilkRoadWorkspace title="营销视频生成"><section class="head"><div><span>VIDEO GENERATION</span><h1>商品营销视频素材</h1><p>从商品画面和目标市场表达生成演示、广告与数字人口播背景视频。</p></div><el-button @click="router.push('/media/image')">前往图片生成</el-button></section><section class="generator"><el-form label-position="top"><div class="form-grid"><el-form-item label="关联营销项目"><el-select v-model="form.projectId"><el-option v-for="item in projects" :key="item.id" :label="item.product_name" :value="String(item.id)"/></el-select></el-form-item><el-form-item label="画面比例"><el-select v-model="form.aspect"><el-option label="9:16 竖屏" value="9:16"/><el-option label="16:9 横屏" value="16:9"/><el-option label="1:1 方形" value="1:1"/></el-select></el-form-item></div><el-form-item label="参考图片地址"><el-input v-model="form.imageUrl" placeholder="可填写项目商品图或已生成营销素材地址"/></el-form-item><el-form-item label="视频画面提示"><el-input v-model="form.prompt" type="textarea" :rows="4" placeholder="描述商品动作、镜头运动、使用环境、光线和目标市场视觉风格"/></el-form-item><el-button type="primary" :loading="generating" :disabled="!form.projectId||!form.prompt" @click="generate">生成营销视频</el-button></el-form></section><h2 class="section-title">最近生成</h2><div v-loading="loading" class="media-grid"><article v-for="item in videos" :key="item.id"><video v-if="item.video_url" :src="item.video_url" controls/><div v-else class="placeholder"><el-icon><VideoPlay /></el-icon></div><el-tag :type="item.status==='completed'?'success':item.status==='failed'?'danger':'warning'">{{ statusText(item.status) }}</el-tag><p>{{ item.prompt }}</p></article></div><el-empty v-if="!loading&&!videos.length" description="暂无营销视频生成记录"/></SilkRoadWorkspace></template>
<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import{VideoPlay}from'@element-plus/icons-vue';import{useRoute,useRouter}from'vue-router';import SilkRoadWorkspace from '@/layouts/SilkRoadWorkspace.vue';import{projectAPI}from'@/api/project';import{mediaGenerationAPI}from'@/api/media-generation';import type{MarketingProject}from'@/types/project';import type{VideoGeneration}from'@/types/video';const route=useRoute(),router=useRouter(),projects=ref<MarketingProject[]>([]),videos=ref<VideoGeneration[]>([]),loading=ref(false),generating=ref(false),form=reactive({projectId:String(route.query.projectId||''),aspect:'9:16',imageUrl:'',prompt:''});const statusText=(s:string)=>({pending:'等待中',processing:'生成中',completed:'已完成',failed:'失败'}[s]||s);const load=async()=>{loading.value=true;try{projects.value=(await projectAPI.list({page_size:100})).items;if(!form.projectId&&projects.value[0])form.projectId=String(projects.value[0].id);videos.value=(await mediaGenerationAPI.videos.listByProject(form.projectId||undefined)).items||[]}finally{loading.value=false}};const generate=async()=>{generating.value=true;try{await mediaGenerationAPI.videos.generateForProject({project_id:form.projectId,prompt:form.prompt,image_url:form.imageUrl||undefined,aspect_ratio:form.aspect,duration:5});ElMessage.success('营销视频生成任务已提交');await load()}catch(e:any){ElMessage.error(e?.message||'视频生成失败')}finally{generating.value=false}};onMounted(load)</script>
<style scoped>.head{display:flex;align-items:end;justify-content:space-between;margin-bottom:22px}.head span{font-size:12px;letter-spacing:.16em;color:var(--accent);font-weight:800}.head h1{font-size:30px;margin:8px 0}.head p{color:var(--text-secondary)}.generator{padding:23px;border:1px solid var(--border-primary);border-radius:20px;background:var(--bg-card)}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.generator .el-select{width:100%}.section-title{margin:28px 0 16px}.media-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:16px;min-height:100px}.media-grid article{padding:12px;border:1px solid var(--border-primary);border-radius:16px;background:var(--bg-card)}.media-grid video,.placeholder{width:100%;height:170px;object-fit:cover;border-radius:11px;background:var(--bg-muted)}.placeholder{display:grid;place-items:center;font-size:42px}.media-grid .el-tag{margin-top:12px}.media-grid p{margin-top:9px;color:var(--text-secondary);height:42px;overflow:hidden}</style>
